arguments.cmd:
cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="Global Aid Alliance delivers disaster relief, emergency assistance, and resilience programs worldwide. Donate or volunteer to help communities in crisis." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Sora:wght@600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --red-900: #7b0f17;
      --red-700: #b11c2b;
      --red-600: #c42a35;
      --navy-900: #102340;
      --navy-700: #1e3a68;
      --ink-900: #1d222c;
      --ink-700: #404958;
      --paper: #ffffff;
      --warm-50: #fcfaf8;
      --warm-100: #f5f0ec;
      --warm-200: #e9dfd7;
      --line: #e6ddd5;
      --success: #1d7c4a;
      --shadow: 0 16px 40px rgba(16, 35, 64, 0.14);
      --radius: 16px;
      --max: 1160px;
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; scroll-behavior: smooth; }
    body {
      font-family: "Plus Jakarta Sans", sans-serif;
      color: var(--ink-900);
      background: linear-gradient(to bottom, var(--paper), var(--warm-50));
      line-height: 1.55;
    }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }

    .container { width: min(var(--max), 92%); margin: 0 auto; }

    .eyebrow {
      font-size: .8rem;
      font-weight: 700;
      letter-spacing: .12em;
      text-transform: uppercase;
      color: var(--red-700);
    }

    .section-title {
      font-family: "Sora", sans-serif;
      font-size: clamp(1.6rem, 2.5vw, 2.4rem);
      line-height: 1.2;
      margin: .45rem 0 .8rem;
    }

    .section-copy {
      color: var(--ink-700);
      max-width: 68ch;
      margin: 0;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 40;
      background: rgba(255,255,255,.95);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--line);
    }

    .nav-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 76px;
      gap: 1rem;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: .7rem;
      font-weight: 800;
      color: var(--navy-900);
    }

    .brand-mark {
      width: 40px; height: 40px;
      border-radius: 11px;
      background: conic-gradient(from 90deg, var(--red-700), var(--red-900), var(--navy-700));
      box-shadow: inset 0 0 0 2px rgba(255,255,255,.45);
    }

    .desktop-nav {
      display: flex;
      align-items: center;
      gap: 1.25rem;
      font-weight: 600;
      color: var(--ink-700);
    }

    .desktop-nav a:hover { color: var(--navy-900); }

    .btn {
      border: 0;
      border-radius: 999px;
      padding: .78rem 1.2rem;
      font-weight: 700;
      cursor: pointer;
      font-family: inherit;
      transition: transform .2s ease, box-shadow .2s ease, background-color .2s ease;
    }

    .btn:hover { transform: translateY(-1px); }
    .btn:focus-visible, .icon-btn:focus-visible, .accordion-toggle:focus-visible,
    .close-modal:focus-visible, .amount-option:focus-visible, .menu-btn:focus-visible {
      outline: 3px solid rgba(16,35,64,.28);
      outline-offset: 2px;
    }

    .btn-primary {
      background: linear-gradient(135deg, var(--red-700), var(--red-900));
      color: #fff;
      box-shadow: 0 12px 26px rgba(123, 15, 23, .28);
    }

    .btn-secondary {
      background: var(--navy-900);
      color: #fff;
    }

    .btn-light {
      background: #fff;
      color: var(--navy-900);
      border: 1px solid var(--line);
    }

    .menu-btn {
      display: none;
      border: 1px solid var(--line);
      background: #fff;
      width: 42px;
      height: 42px;
      border-radius: 10px;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      color: var(--navy-900);
    }

    .mobile-drawer {
      display: none;
      border-top: 1px solid var(--line);
      transform-origin: top;
      animation: drawerIn .24s ease;
    }

    .mobile-drawer a {
      display: block;
      padding: .95rem 0;
      border-bottom: 1px solid var(--warm-100);
      color: var(--ink-700);
      font-weight: 600;
    }

    .mobile-drawer .btn { margin: .9rem 0 1.2rem; width: 100%; }

    @keyframes drawerIn {
      from { opacity: 0; transform: translateY(-8px) scaleY(.98); }
      to { opacity: 1; transform: translateY(0) scaleY(1); }
    }

    .hero {
      padding: clamp(2.6rem, 7vw, 6rem) 0 3rem;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr .9fr;
      gap: clamp(1.3rem, 3vw, 2.2rem);
      align-items: center;
    }

    .hero h1 {
      margin: .4rem 0 1rem;
      font-family: "Sora", sans-serif;
      font-size: clamp(2rem, 5vw, 3.8rem);
      line-height: 1.08;
      letter-spacing: -.03em;
      max-width: 14ch;
      color: var(--navy-900);
    }

    .hero p {
      margin: 0;
      color: var(--ink-700);
      font-size: clamp(1rem, 1.7vw, 1.12rem);
      max-width: 58ch;
    }

    .hero-actions {
      display: flex;
      gap: .8rem;
      margin-top: 1.6rem;
      flex-wrap: wrap;
    }

    .hero-media {
      border-radius: calc(var(--radius) + 6px);
      overflow: hidden;
      box-shadow: var(--shadow);
      position: relative;
      min-height: 340px;
    }

    .hero-media img { height: 100%; width: 100%; object-fit: cover; }

    .hero-media::after {
      content: "On the ground in 48 hours";
      position: absolute;
      left: 16px;
      bottom: 16px;
      color: #fff;
      font-weight: 700;
      background: rgba(16,35,64,.72);
      padding: .5rem .75rem;
      border-radius: 999px;
      font-size: .82rem;
    }

    section { padding: 3.6rem 0; }

    .mission-box {
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: #fff;
      padding: clamp(1.2rem, 3.2vw, 2rem);
      box-shadow: 0 10px 26px rgba(45, 57, 78, .07);
    }

    .stats-wrap {
      background: linear-gradient(170deg, var(--navy-900), var(--navy-700));
      color: #fff;
      border-radius: calc(var(--radius) + 10px);
      padding: clamp(1.3rem, 4vw, 2.4rem);
    }

    .stats-grid {
      margin-top: 1.2rem;
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .stat {
      background: rgba(255,255,255,.06);
      border: 1px solid rgba(255,255,255,.14);
      border-radius: 14px;
      padding: 1rem;
      text-align: center;
    }

    .stat-value {
      font-family: "Sora", sans-serif;
      font-size: clamp(1.65rem, 2.6vw, 2.3rem);
      line-height: 1.15;
      font-weight: 800;
    }

    .stat-label { opacity: .9; font-size: .94rem; margin-top: .45rem; }

    .programs-layout {
      display: grid;
      gap: 1rem;
      margin-top: 1.3rem;
    }

    .accordion-item {
      border: 1px solid var(--line);
      border-radius: 14px;
      background: #fff;
      overflow: clip;
    }

    .accordion-toggle {
      width: 100%;
      text-align: left;
      border: 0;
      background: #fff;
      padding: 1rem 1.1rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      font-family: inherit;
      cursor: pointer;
    }

    .accordion-toggle strong {
      font-size: 1.05rem;
      color: var(--navy-900);
    }

    .accordion-toggle span { color: var(--ink-700); font-size: .95rem; }

    .chevron {
      width: 28px;
      height: 28px;
      border-radius: 999px;
      border: 1px solid var(--line);
      display: grid;
      place-items: center;
      color: var(--ink-700);
      transition: transform .24s ease;
      flex-shrink: 0;
    }

    .accordion-item.open .chevron { transform: rotate(180deg); }

    .accordion-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height .28s ease;
      border-top: 1px solid transparent;
      background: var(--warm-50);
    }

    .accordion-item.open .accordion-content {
      border-top-color: var(--line);
    }

    .accordion-content-inner {
      padding: 1rem 1.1rem 1.2rem;
      color: var(--ink-700);
    }

    .split {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.2rem;
      align-items: stretch;
    }

    .card {
      background: #fff;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      padding: clamp(1rem, 2.2vw, 1.5rem);
      box-shadow: 0 10px 24px rgba(33,44,60,.05);
    }

    .news-shell {
      margin-top: 1.2rem;
      border: 1px solid var(--line);
      border-radius: calc(var(--radius) + 2px);
      background: #fff;
      overflow: hidden;
    }

    .news-track {
      display: flex;
      transition: transform .35s ease;
    }

    .news-slide {
      min-width: 100%;
      padding: 1rem;
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 1rem;
    }

    .news-card {
      border: 1px solid var(--warm-200);
      border-radius: 14px;
      overflow: hidden;
      background: #fff;
      display: grid;
      grid-template-rows: 180px 1fr;
    }

    .news-card img { width: 100%; height: 100%; object-fit: cover; }

    .news-body { padding: .9rem .9rem 1rem; }

    .news-body h4 {
      margin: .15rem 0 .45rem;
      font-size: 1.04rem;
      color: var(--navy-900);
      line-height: 1.3;
    }

    .news-body p { margin: 0; color: var(--ink-700); font-size: .94rem; }

    .meta { color: var(--red-700); font-weight: 700; font-size: .78rem; text-transform: uppercase; letter-spacing: .07em; }

    .news-controls {
      display: flex;
      justify-content: flex-end;
      gap: .5rem;
      padding: .7rem .9rem .95rem;
      border-top: 1px solid var(--line);
      background: var(--warm-50);
    }

    .icon-btn {
      border: 1px solid var(--line);
      width: 38px;
      height: 38px;
      border-radius: 10px;
      display: grid;
      place-items: center;
      background: #fff;
      cursor: pointer;
      color: var(--navy-900);
    }

    .cta-band {
      background: linear-gradient(140deg, #8d151f, var(--red-900));
      color: #fff;
      border-radius: calc(var(--radius) + 6px);
      padding: clamp(1.2rem, 3.6vw, 2rem);
      display: grid;
      grid-template-columns: 1.1fr auto;
      gap: 1rem;
      align-items: center;
      box-shadow: var(--shadow);
    }

    .cta-band h3 { margin: .25rem 0 .5rem; font-size: clamp(1.3rem, 2vw, 1.8rem); }
    .cta-band p { margin: 0; opacity: .95; max-width: 52ch; }

    footer {
      margin-top: 2rem;
      padding: 2.5rem 0;
      border-top: 1px solid var(--line);
      background: #fff;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1.1rem;
      margin: 1rem 0 1.5rem;
    }

    .footer-grid h4 {
      margin: 0 0 .5rem;
      color: var(--navy-900);
      font-size: .98rem;
    }

    .footer-grid a {
      display: block;
      color: var(--ink-700);
      font-size: .92rem;
      margin: .4rem 0;
    }

    .footer-base {
      border-top: 1px solid var(--line);
      padding-top: 1rem;
      font-size: .9rem;
      color: var(--ink-700);
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .modal {
      position: fixed;
      inset: 0;
      z-index: 60;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 1rem;
      background: rgba(15, 23, 39, 0.62);
      backdrop-filter: blur(3px);
    }

    .modal.show { display: flex; }

    .modal-card {
      width: min(640px, 100%);
      background: #fff;
      border-radius: 18px;
      border: 1px solid var(--line);
      box-shadow: var(--shadow);
      overflow: hidden;
      animation: pop .22s ease;
    }

    @keyframes pop {
      from { transform: translateY(10px) scale(.98); opacity: 0; }
      to { transform: translateY(0) scale(1); opacity: 1; }
    }

    .modal-head {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 1rem;
      padding: 1.2rem 1.2rem .8rem;
      border-bottom: 1px solid var(--line);
    }

    .modal-head h3 { margin: 0; color: var(--navy-900); }
    .modal-head p { margin: .4rem 0 0; color: var(--ink-700); font-size: .95rem; }

    .close-modal {
      border: 1px solid var(--line);
      background: #fff;
      width: 34px; height: 34px;
      border-radius: 10px;
      cursor: pointer;
      font-size: 1.05rem;
      color: var(--ink-700);
    }

    .donation-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: .65rem;
      padding: 1rem 1.2rem;
    }

    .amount-option {
      border: 1px solid var(--line);
      border-radius: 12px;
      background: #fff;
      padding: .8rem .7rem;
      text-align: left;
      font-family: inherit;
      cursor: pointer;
      min-height: 88px;
    }

    .amount-option strong { display: block; color: var(--navy-900); }
    .amount-option small { color: var(--ink-700); font-size: .8rem; }

    .amount-option.selected {
      border-color: var(--red-700);
      background: #fff4f4;
      box-shadow: inset 0 0 0 1px rgba(177,28,43,.16);
    }

    .modal-actions {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: .8rem;
      border-top: 1px solid var(--line);
      padding: .9rem 1.2rem 1.2rem;
      flex-wrap: wrap;
    }

    .selected-note { color: var(--success); font-weight: 700; font-size: .92rem; }

    @media (max-width: 1024px) {
      .stats-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .hero-grid { grid-template-columns: 1fr; }
      .split { grid-template-columns: 1fr; }
      .cta-band { grid-template-columns: 1fr; }
    }

    @media (max-width: 860px) {
      .desktop-nav { display: none; }
      .menu-btn { display: inline-flex; }
      .mobile-drawer.show { display: block; }
      .news-slide { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }

    @media (max-width: 600px) {
      .stats-grid { grid-template-columns: 1fr; }
      .donation-grid { grid-template-columns: 1fr 1fr; }
      .hero-actions .btn { width: 100%; }
      .footer-grid { grid-template-columns: 1fr; }
      .modal-actions .btn { width: 100%; }
    }
  </style>
</head>
<body>
  <header>
    <div class="container">
      <div class="nav-row">
        <a class="brand" href="#home" aria-label="Global Aid Alliance home">
          <span class="brand-mark" aria-hidden="true"></span>
          <span>Global Aid Alliance</span>
        </a>

        <nav class="desktop-nav" aria-label="Primary">
          <a href="#programs">Disaster Relief</a>
          <a href="#mission">About Us</a>
          <a href="#get-involved">Volunteer</a>
          <a href="#news">News</a>
          <button class="btn btn-primary" data-open-donate>Donate</button>
        </nav>

        <button class="menu-btn" id="menuBtn" aria-expanded="false" aria-controls="mobileNav" aria-label="Open menu">
          ☰
        </button>
      </div>

      <nav id="mobileNav" class="mobile-drawer" aria-label="Mobile">
        <a href="#programs">Disaster Relief</a>
        <a href="#mission">About Us</a>
        <a href="#get-involved">Volunteer</a>
        <a href="#news">News</a>
        <a href="#footer">Find Local Chapter</a>
        <button class="btn btn-primary" data-open-donate>Donate</button>
      </nav>
    </div>
  </header>

  <main id="home">
    <section class="hero">
      <div class="container hero-grid">
        <div>
          <p class="eyebrow">Global emergency response</p>
          <h1>Together We Respond When Communities Need Help Most</h1>
          <p>
            Global Aid Alliance delivers disaster relief, emergency assistance, and long-term resilience programs in partnership with local communities worldwide.
          </p>
          <div class="hero-actions">
            <button class="btn btn-primary" data-open-donate>Donate Now</button>
            <a class="btn btn-light" href="#get-involved">Become a Volunteer</a>
          </div>
        </div>
        <figure class="hero-media">
          <img src="https://images.unsplash.com/photo-1469571486292-b53601020b9e?auto=format&fit=crop&w=1200&q=80" alt="Relief workers distributing emergency supplies to families after a natural disaster" loading="lazy" />
        </figure>
      </div>
    </section>

    <section id="mission">
      <div class="container mission-box">
        <p class="eyebrow">Our Mission</p>
        <h2 class="section-title">Save lives, reduce suffering, and build resilience before the next crisis.</h2>
        <p class="section-copy">We mobilize fast, coordinate locally, and stay committed long after headlines fade. Our teams support emergency shelter, food security, health services, and preparedness training in regions facing climate disasters, conflict, and public health shocks.</p>
      </div>
    </section>

    <section id="impact">
      <div class="container stats-wrap">
        <p class="eyebrow" style="color:#ffd9de;">Impact Statistics</p>
        <h2 class="section-title" style="margin-top:.5rem; color:#fff;">Global reach backed by measurable outcomes</h2>
        <div class="stats-grid" aria-label="Key organizational impact metrics">
          <article class="stat">
            <div class="stat-value" data-counter data-target="12" data-suffix="M+">0</div>
            <div class="stat-label">People helped</div>
          </article>
          <article class="stat">
            <div class="stat-value" data-counter data-target="50" data-suffix="K+">0</div>
            <div class="stat-label">Volunteers mobilized</div>
          </article>
          <article class="stat">
            <div class="stat-value" data-counter data-target="190">0</div>
            <div class="stat-label">Countries supported</div>
          </article>
          <article class="stat">
            <div class="stat-value" data-counter data-target="850" data-prefix="$" data-suffix="M">0</div>
            <div class="stat-label">Raised for relief</div>
          </article>
        </div>
      </div>
    </section>

    <section id="programs">
      <div class="container">
        <p class="eyebrow">Programs and Services</p>
        <h2 class="section-title">Integrated support from immediate response to long-term recovery</h2>
        <div class="programs-layout" id="programAccordion">
          <article class="accordion-item open">
            <button class="accordion-toggle" aria-expanded="true">
              <div><strong>Disaster Relief</strong><br><span>Emergency shelter, food, water, and medical aid</span></div>
              <span class="chevron">⌄</span>
            </button>
            <div class="accordion-content" style="max-height: 180px;">
              <div class="accordion-content-inner">Rapid-response teams deploy supplies, mobile clinics, and logistics support within 48 hours to stabilize affected communities.</div>
            </div>
          </article>
          <article class="accordion-item">
            <button class="accordion-toggle" aria-expanded="false">
              <div><strong>Blood Donation</strong><br><span>Safe blood collection and emergency blood drives</span></div>
              <span class="chevron">⌄</span>
            </button>
            <div class="accordion-content"><div class="accordion-content-inner">We coordinate national and local blood drives with partner hospitals to maintain lifesaving blood inventories during crises.</div></div>
          </article>
          <article class="accordion-item">
            <button class="accordion-toggle" aria-expanded="false">
              <div><strong>Emergency Preparedness</strong><br><span>Training households, schools, and local responders</span></div>
              <span class="chevron">⌄</span>
            </button>
            <div class="accordion-content"><div class="accordion-content-inner">Preparedness workshops, evacuation planning, and early warning education reduce risk and speed recovery after disasters.</div></div>
          </article>
          <article class="accordion-item">
            <button class="accordion-toggle" aria-expanded="false">
              <div><strong>International Humanitarian Aid</strong><br><span>Cross-border assistance in conflict and displacement settings</span></div>
              <span class="chevron">⌄</span>
            </button>
            <div class="accordion-content"><div class="accordion-content-inner">In partnership with local NGOs, we deliver dignified aid packages, health services, and cash assistance in fragile contexts.</div></div>
          </article>
          <article class="accordion-item">
            <button class="accordion-toggle" aria-expanded="false">
              <div><strong>Community Health</strong><br><span>Public health outreach and resilience services</span></div>
              <span class="chevron">⌄</span>
            </button>
            <div class="accordion-content"><div class="accordion-content-inner">Our community health teams provide preventive care access, hygiene kits, and recovery support for vulnerable populations.</div></div>
          </article>
        </div>
      </div>
    </section>

    <section id="get-involved">
      <div class="container split">
        <article class="card">
          <p class="eyebrow">Volunteer</p>
          <h3 style="margin:.35rem 0 .55rem; color:var(--navy-900);">Bring your skills to the front lines of response</h3>
          <p class="section-copy">From logistics and translation to first aid and digital support, volunteers extend our reach and strengthen local capacity.</p>
          <a href="#footer" class="btn btn-secondary" style="margin-top:1rem; display:inline-block;">Find Local Chapter</a>
        </article>
        <article class="card">
          <p class="eyebrow">Accountability</p>
          <h3 style="margin:.35rem 0 .55rem; color:var(--navy-900);">Trusted stewardship of every contribution</h3>
          <p class="section-copy">91 cents of every dollar supports humanitarian programs. We publish independent audits and transparent annual financial reports.</p>
          <a href="#footer" class="btn btn-light" style="margin-top:1rem; display:inline-block;">View Financials</a>
        </article>
      </div>
    </section>

    <section id="news">
      <div class="container">
        <p class="eyebrow">Latest News</p>
        <h2 class="section-title">Updates from current relief efforts</h2>
        <div class="news-shell" aria-label="News carousel">
          <div class="news-track" id="newsTrack">
            <div class="news-slide">
