      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: .65rem;
      padding: 1rem 1.2rem;
    }

    .amount-option {
      border: 1px solid var(--line);
      border-radius: 12px;
      background: #fff;
      padding: .8rem .7rem;
      text-align: left;
      font-family: inherit;
      cursor: pointer;
      min-height: 88px;
    }

    .amount-option strong { display: block; color: var(--navy-900); }
    .amount-option small { color: var(--ink-700); font-size: .8rem; }

    .amount-option.selected {
      border-color: var(--red-700);
      background: #fff4f4;
      box-shadow: inset 0 0 0 1px rgba(177,28,43,.16);
    }

    .modal-actions {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: .8rem;
      border-top: 1px solid var(--line);
      padding: .9rem 1.2rem 1.2rem;
      flex-wrap: wrap;
    }

    .selected-note { color: var(--success); font-weight: 700; font-size: .92rem; }

    @media (max-width: 1024px) {
      .stats-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .hero-grid { grid-template-columns: 1fr; }
      .split { grid-template-columns: 1fr; }
      .cta-band { grid-template-columns: 1fr; }
    }

    @media (max-width: 860px) {
      .desktop-nav { display: none; }
      .menu-btn { display: inline-flex; }
      .mobile-drawer.show { display: block; }
      .news-slide { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }

    @media (max-width: 600px) {
      .stats-grid { grid-template-columns: 1fr; }
      .donation-grid { grid-template-columns: 1fr 1fr; }
      .hero-actions .btn { width: 100%; }
      .footer-grid { grid-template-columns: 1fr; }
      .modal-actions .btn { width: 100%; }
    }
  </style>
</head>
<body>
