  <div class="modal" id="donateModal" role="dialog" aria-modal="true" aria-labelledby="donateTitle">
    <div class="modal-card">
      <div class="modal-head">
        <div>
          <h3 id="donateTitle">Make a lifesaving donation</h3>
          <p>Your contribution powers immediate response and long-term recovery for communities in crisis.</p>
        </div>
        <button class="close-modal" id="closeDonate" aria-label="Close donation dialog">✕</button>
