      <div class="donation-grid" id="amountGrid">
        <button class="amount-option selected" data-amount="$25"><strong>$25</strong><small>5 emergency blankets</small></button>
        <button class="amount-option" data-amount="$50"><strong>$50</strong><small>Food + water for one week</small></button>
        <button class="amount-option" data-amount="$100"><strong>$100</strong><small>Emergency shelter materials</small></button>
        <button class="amount-option" data-amount="$250"><strong>$250</strong><small>Volunteer disaster training</small></button>
        <button class="amount-option" data-amount="Custom"><strong>Custom</strong><small>Every dollar saves lives</small></button>
      </div>

      <div class="modal-actions">
        <span class="selected-note" id="selectedAmount">Selected: $25</span>
        <button class="btn btn-primary">Donate Now</button>
      </div>
