  <script>
    const menuBtn = document.getElementById('menuBtn');
    const mobileNav = document.getElementById('mobileNav');
    menuBtn.addEventListener('click', () => {
      const open = mobileNav.classList.toggle('show');
      menuBtn.setAttribute('aria-expanded', String(open));
      menuBtn.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
      menuBtn.textContent = open ? '✕' : '☰';
    });

    mobileNav.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        mobileNav.classList.remove('show');
        menuBtn.setAttribute('aria-expanded', 'false');
        menuBtn.setAttribute('aria-label', 'Open menu');
        menuBtn.textContent = '☰';
      });
    });

    const donateModal = document.getElementById('donateModal');
    const openDonateButtons = document.querySelectorAll('[data-open-donate]');
    const closeDonate = document.getElementById('closeDonate');

    const openModal = () => {
      donateModal.classList.add('show');
      document.body.style.overflow = 'hidden';
    };

    const closeModal = () => {
      donateModal.classList.remove('show');
      document.body.style.overflow = '';
    };

    openDonateButtons.forEach(btn => btn.addEventListener('click', openModal));
    closeDonate.addEventListener('click', closeModal);
    donateModal.addEventListener('click', (e) => {
      if (e.target === donateModal) closeModal();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && donateModal.classList.contains('show')) closeModal();
    });

    const amountGrid = document.getElementById('amountGrid');
    const selectedAmountText = document.getElementById('selectedAmount');
    amountGrid.addEventListener('click', (e) => {
      const button = e.target.closest('.amount-option');
      if (!button) return;
      amountGrid.querySelectorAll('.amount-option').forEach(option => option.classList.remove('selected'));
      button.classList.add('selected');
      selectedAmountText.textContent = `Selected: ${button.dataset.amount}`;
    });

    const accordion = document.getElementById('programAccordion');
    accordion.querySelectorAll('.accordion-item').forEach((item) => {
      const toggle = item.querySelector('.accordion-toggle');
      const content = item.querySelector('.accordion-content');

      toggle.addEventListener('click', () => {
        const isOpen = item.classList.contains('open');
        accordion.querySelectorAll('.accordion-item').forEach((other) => {
          other.classList.remove('open');
          other.querySelector('.accordion-toggle').setAttribute('aria-expanded', 'false');
          other.querySelector('.accordion-content').style.maxHeight = '0px';
        });

        if (!isOpen) {
          item.classList.add('open');
          toggle.setAttribute('aria-expanded', 'true');
          content.style.maxHeight = content.scrollHeight + 'px';
        }
      });
    });

    const newsTrack = document.getElementById('newsTrack');
    const prevNews = document.getElementById('prevNews');
    const nextNews = document.getElementById('nextNews');
    const slideCount = newsTrack.children.length;
    let currentSlide = 0;

    function renderSlide() {
      newsTrack.style.transform = `translateX(-${currentSlide * 100}%)`;
    }

    nextNews.addEventListener('click', () => {
      currentSlide = (currentSlide + 1) % slideCount;
      renderSlide();
    });

    prevNews.addEventListener('click', () => {
      currentSlide = (currentSlide - 1 + slideCount) % slideCount;
      renderSlide();
    });

    const counters = document.querySelectorAll('[data-counter]');
    const counterObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        const el = entry.target;
        const target = Number(el.dataset.target || 0);
        const prefix = el.dataset.prefix || '';
        const suffix = el.dataset.suffix || '';
        const duration = 1100;
        const start = performance.now();

        function update(now) {
          const progress = Math.min((now - start) / duration, 1);
          const value = Math.floor(progress * target);
          el.textContent = `${prefix}${value}${suffix}`;
          if (progress < 1) requestAnimationFrame(update);
          else el.textContent = `${prefix}${target}${suffix}`;
        }

        requestAnimationFrame(update);
        observer.unobserve(el);
      });
    }, { threshold: .45 });

    counters.forEach(counter => counterObserver.observe(counter));
  </script>
</body>
